const attemptsRaw=$('Attempts Today').first().json||{};
const countRaw=$('Count Today').first().json||{};
const rows=Array.isArray(attemptsRaw.data)?attemptsRaw.data:null;
const countRows=Array.isArray(countRaw.data)?countRaw.data:null;
const expected=countRows?.[0]?.count?.id;
if(!rows || expected===undefined || expected===null){
  return [{json:{ok:false,error:'Directus non ha restituito una risposta valida. Nessun KPI viene calcolato.',error_code:'DB_RESPONSE_INVALID'}}];
}
const expectedN=Number(expected||0);
if(rows.length!==expectedN){
  return [{json:{ok:false,error:`Dataset parziale: ricevute ${rows.length} righe su ${expectedN}. Nessun KPI viene calcolato.`,error_code:'DATASET_TRUNCATED',rows_returned:rows.length,rows_expected:expectedN}}];
}
const prodVal=v=>v===false||v===0||String(v).toLowerCase()==='false';
const testVal=v=>v===true||v===1||String(v).toLowerCase()==='true';
const prod=rows.filter(a=>prodVal(a.test_mode));
const testCount=rows.filter(a=>testVal(a.test_mode)).length;
const envUnknown=rows.length-prod.length-testCount;
const bump=(o,k)=>{const key=(k===null||k===undefined||String(k).trim()==='')?'missing':String(k);o[key]=(o[key]||0)+1};
const validRespondent=v=>['human','ivr','ai_voice','voicemail'].includes(String(v||'').toLowerCase());
const purposeAnalysisAvailable=v=>!['','unknown','unkown'].includes(String(v??'').trim().toLowerCase());
const purposeDetermined=v=>['commercial','support','private','reception'].includes(String(v||'').toLowerCase());
const serviceDetermined=v=>!['','unknown','unkown','none'].includes(String(v??'').trim().toLowerCase());
const div=(a,b)=>b?a/b:null;
const technical={},respondent={},attemptVerdicts={};
let completed=0,spam=0,dur=0,durN=0,rOk=0,pAnalysis=0,pDetermined=0,sDetermined=0;
for(const a of prod){
  bump(technical,a.call_status||'unknown');
  if(a.call_status!=='completed') continue;
  completed++;
  bump(respondent,a.respondent_type||'unknown');
  bump(attemptVerdicts,a.verdict||'undecided');
  if(a.verdict==='spam') spam++;
  const d=Number(a.call_duration_seconds);if(Number.isFinite(d)&&d>0){dur+=d;durN++;}
  if(validRespondent(a.respondent_type)) rOk++;
  if(purposeAnalysisAvailable(a.purpose)) pAnalysis++;
  if(validRespondent(a.respondent_type)&&purposeDetermined(a.purpose)) pDetermined++;
  if(validRespondent(a.respondent_type)&&purposeDetermined(a.purpose)&&serviceDetermined(a.service_category)) sDetermined++;
}
const warnings=[];
if(envUnknown>0) warnings.push(`${envUnknown} record nel giorno hanno ambiente non certificabile e sono esclusi dai KPI produzione.`);
return [{json:{
  ok:true,generated_at:new Date().toISOString(),
  range:{timezone:'Europe/Rome',basis:'mt_call_attempts.start_time',local_date:$('Prepare Today').first().json.local_date},
  scope:{production_rule:'test_mode === false',production_rows:prod.length,test_rows_excluded:testCount,environment_unknown_excluded:envUnknown,total_rows_in_range:rows.length},
  macro:{calls_registered_today:prod.length,completed_today:completed,completed_rate:div(completed,prod.length),avg_duration_sec:durN?dur/durN:null,spam_rate_completed:div(spam,completed)},
  technical,respondent,attempt_verdicts:attemptVerdicts,
  data_quality:{respondent_determined_rate:div(rOk,completed),purpose_analysis_available_rate:div(pAnalysis,completed),purpose_determined_rate:div(pDetermined,completed),service_determined_rate:div(sDetermined,completed),respondent_missing:completed-rOk,purpose_analysis_missing:completed-pAnalysis,purpose_not_determined:completed-pDetermined,service_not_determined:completed-sDetermined,environment_unknown:envUnknown,test_excluded:testCount},
  source_integrity:{rows_expected:expectedN,rows_returned:rows.length,complete:true},warnings
}}];
